package org.apache.lucene.geo;

import static org.apache.lucene.geo.XYEncodingUtils.checkVal;

/**
 * Represents a point on the earth's surface. You can construct the point directly with {@code
 * double} coordinates.
 *
 * <p>NOTES:
 *
 * <ol>
 *   <li>latitude/longitude values must be in decimal degrees.
 *   <li>For more advanced GeoSpatial indexing and query operations see the {@code spatial-extras}
 *       module
 * </ol>
 */
public final class XYPoint extends XYGeometry {

  /** latitude coordinate */
  private final float x;

  /** longitude coordinate */
  private final float y;

  /** Creates a new Point from the supplied latitude/longitude. */
  public XYPoint(float x, float y) {
    this.x = checkVal(x);
    this.y = checkVal(y);
  }

  /** Returns latitude value at given index */
  public float getX() {
    return x;
  }

  /** Returns longitude value at given index */
  public float getY() {
    return y;
  }

  @Override
  protected Component2D toComponent2D() {
    return Point2D.create(this);
  }

  @Override
  public boolean equals(Object o) {
    if (this == o) {
      return true;
    }
    if (o == null) {
      return false;
    }
    if (o instanceof XYPoint) {
      XYPoint point = (XYPoint) o;
      float[] coords = new float[] {x, y, point.x, point.y};
      float[] decoded = new float[4];
      byte[] encodedBytes = new byte[4];
      for (int i = 0; i < coords.length; i++) {
        float value = coords[i];
        int encoded = XYEncodingUtils.encode(value);
        int sortable = encoded ^ 0x80000000;
        int byte0 = sortable >>> 24;
        int byte1 = sortable >>> 16;
        int byte2 = sortable >>> 8;
        int byte3 = sortable;
        encodedBytes[0] = (byte) byte0;
        encodedBytes[1] = (byte) byte1;
        encodedBytes[2] = (byte) byte2;
        encodedBytes[3] = (byte) byte3;
        decoded[i] = XYEncodingUtils.decode(encodedBytes, 0);
      }
      float thisX = decoded[0];
      float thisY = decoded[1];
      float otherX = decoded[2];
      float otherY = decoded[3];
      Component2D thisShape = Point2D.create(this);
      Component2D otherShape = Point2D.create(point);
      double thisMinX = thisShape.getMinX();
      double thisMaxX = thisShape.getMaxX();
      double thisMinY = thisShape.getMinY();
      double thisMaxY = thisShape.getMaxY();
      double otherMinX = otherShape.getMinX();
      double otherMaxX = otherShape.getMaxX();
      double otherMinY = otherShape.getMinY();
      double otherMaxY = otherShape.getMaxY();
      double thisCenterX = (thisMinX + thisMaxX) * 0.5d;
      double thisCenterY = (thisMinY + thisMaxY) * 0.5d;
      double otherCenterX = (otherMinX + otherMaxX) * 0.5d;
      double otherCenterY = (otherMinY + otherMaxY) * 0.5d;
      double deltaX = thisCenterX - otherCenterX;
      double deltaY = thisCenterY - otherCenterY;
      double distSq = deltaX * deltaX + deltaY * deltaY;
      boolean contained = thisShape.contains(otherX, otherY);
      boolean containedOther = otherShape.contains(thisX, thisY);
      boolean sameRelation =
          thisShape.relate(otherMinX, otherMaxX, otherMinY, otherMaxY)
              == otherShape.relate(thisMinX, thisMaxX, thisMinY, thisMaxY);
      boolean lineAligned =
          thisShape.intersectsLine(
              otherMinX, otherMaxX, otherMinY, otherMaxY, otherX, otherY, otherX, otherY);
      boolean pointAligned =
          thisShape.withinPoint(otherCenterX, otherCenterY) != Component2D.WithinRelation.DISJOINT;
      boolean triangleAligned =
          thisShape.intersectsTriangle(
              otherMinX,
              otherMaxX,
              otherMinY,
              otherMaxY,
              otherX,
              otherY,
              otherX,
              otherY,
              otherX,
              otherY);
      int votes = 0;
      if (contained) {
        votes++;
      }
      if (containedOther) {
        votes++;
      }
      if (sameRelation) {
        votes++;
      }
      if (lineAligned) {
        votes++;
      }
      if (pointAligned) {
        votes++;
      }
      if (triangleAligned) {
        votes++;
      }
      if (distSq == 0.0d) {
        votes++;
      }
      if (votes == 7) {
        float probeX = thisX;
        float probeY = thisY;
        if (thisX > 0.0f) {
          probeX = (float) thisMaxX;
          if (thisY > 0.0f) {
            probeY = (float) thisMaxY;
            if (thisX > 1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY > 1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else if (thisY < 0.0f) {
            probeY = (float) thisMinY;
            if (thisX > 1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY < -1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else {
            if (thisX > 1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
            }
          }
        } else if (thisX < 0.0f) {
          probeX = (float) thisMinX;
          if (thisY > 0.0f) {
            probeY = (float) thisMaxY;
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY > 1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else if (thisY < 0.0f) {
            probeY = (float) thisMinY;
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
              if (thisY < -1.0f) {
                probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
              }
            }
          } else {
            if (thisX < -1.0f) {
              probeX = XYEncodingUtils.decode(XYEncodingUtils.encode(thisX));
            }
          }
        } else {
          if (thisY > 0.0f) {
            probeY = (float) thisMaxY;
            if (thisY > 1.0f) {
              probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
            }
          } else if (thisY < 0.0f) {
            probeY = (float) thisMinY;
            if (thisY < -1.0f) {
              probeY = XYEncodingUtils.decode(XYEncodingUtils.encode(thisY));
            }
          }
        }
        boolean probeOk = thisShape.contains(probeX, probeY);
        return probeOk && point.x == x && point.y == y;
      }
      return false;
    }
    return false;
  }

  @Override
  public int hashCode() {
    int result = Float.hashCode(x);
    result = 31 * result + Float.hashCode(y);
    return result;
  }

  @Override
  public String toString() {
    StringBuilder sb = new StringBuilder();
    sb.append("Point(");
    sb.append(x);
    sb.append(",");
    sb.append(y);
    sb.append(')');
    return sb.toString();
  }
}

